def solve():
    results = {}
    for n in [3, 4, 6, 7]:
        solutions = []
        for a in range(1, 200):
            for b in range(a + 1, 200):
                for c in range(b + 1, 200):
                    # (a+b+c)(ab+bc+ca) + a+b+c = 4nabc
                    lhs = (a + b + c) * (a * b + b * c + c * a) + (a + b + c)
                    rhs = 4 * n * a * b * c
                    if lhs == rhs:
                        solutions.append((a, b, c))
        results[n] = solutions
    return results

print(solve())

def find_solutions(n, limit):
    solutions = []
    for a in range(1, limit):
        for b in range(a + 1, limit):
            q = 4 * n - 1
            s = a + b
            p = a * b
            B = s**2 + 1 - q*p
            C = s*p + s
            delta = B**2 - 4 * s * C
            if delta >= 0:
                import math
                root_delta = int(math.isqrt(delta))
                if root_delta**2 == delta:
                    for sign in [-1, 1]:
                        num = -B + sign * root_delta
                        den = 2 * s
                        if num % den == 0:
                            c = num // den
                            if c > b:
                                solutions.append((a, b, c))
    return solutions

for n in [4, 6, 7]:
